def transform(grid):
    """
    Fill enclosed 0s with 4s.
    Cells that can reach the grid boundary via 0s stay 0.
    Cells enclosed by 5s (bombs/guards) become 4.
    """
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    visited = [[False]*cols for _ in range(rows)]

    # Direction vectors: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def flood_fill(r, c):
        """BFS flood-fill from cell (r,c) to mark all reachable 0s."""
        stack = [(r, c)]
        visited[r][c] = True

        while stack:
            curr_r, curr_c = stack.pop()
            for dr, dc in directions:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == 0:
                        visited[nr][nc] = True
                        stack.append((nr, nc))

    # Start flood fills from all boundary cells that are 0
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 0:
                flood_fill(r, c)

    for c in [0, cols-1]:
        for r in range(rows):
            if grid[r][c] == 0:
                flood_fill(r, c)

    for r in [0, rows-1]:
        for c in range(cols):
            if grid[r][c] == 0:
                flood_fill(r, c)

    # Enclosed 0s are those not visited (cannot reach boundary)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                result[r][c] = 4

    return result

